-- ADCT, comentários didáticos, lote 6 (arts. 52 a 60, inclusive 54-A), só a partir do texto no banco. Já aplicado.
update legislacao set contexto = $c$Instituições financeiras estrangeiras até a regulamentação do art. 192$c$, aplicacao_pratica = $a$Enquanto não fixadas as condições do art. 192, veda a instalação no País de novas agências de instituições financeiras domiciliadas no exterior (I) e o aumento da participação de pessoas físicas ou jurídicas residentes ou domiciliadas no exterior no capital de instituições financeiras com sede no País (II). O parágrafo único afasta a vedação nas autorizações resultantes de acordos internacionais, de reciprocidade ou de interesse do Governo brasileiro.$a$ where codigo='adct' and numero=52 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Direitos do ex-combatente da Segunda Guerra Mundial$c$, aplicacao_pratica = $a$Assegura ao ex-combatente que efetivamente participou de operações bélicas na Segunda Guerra Mundial, nos termos da Lei nº 5.315/1967, aproveitamento no serviço público sem concurso, com estabilidade (I), pensão especial correspondente à de segundo-tenente das Forças Armadas, requerível a qualquer tempo e inacumulável com rendimentos dos cofres públicos, salvo benefícios previdenciários e o direito de opção (II), pensão por morte à viúva, companheira ou dependente, de forma proporcional (III), assistência médica, hospitalar e educacional gratuita extensiva aos dependentes (IV), aposentadoria integral aos vinte e cinco anos de serviço efetivo em qualquer regime (V) e prioridade na aquisição da casa própria (VI). Pelo parágrafo único, a pensão especial do inciso II substitui qualquer outra pensão já concedida ao ex-combatente.$a$ where codigo='adct' and numero=53 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Pensão vitalícia dos seringueiros$c$, aplicacao_pratica = $a$Garante aos seringueiros recrutados nos termos do Decreto-Lei nº 5.813/1943 e amparados pelo Decreto-Lei nº 9.882/1946, quando carentes, pensão mensal vitalícia de dois salários mínimos. O § 1º estende o benefício aos que, atendendo a apelo do Governo, trabalharam na produção de borracha na Região Amazônica durante a Segunda Guerra Mundial, o § 2º permite a transferência aos dependentes reconhecidamente carentes e o § 3º remeteu a concessão a lei a ser proposta pelo Poder Executivo em cento e cinquenta dias da promulgação.$a$ where codigo='adct' and numero=54 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Indenização aos seringueiros$c$, aplicacao_pratica = $a$Assegura aos seringueiros de que trata o art. 54 do ADCT indenização em parcela única de R$ 25.000,00 (vinte e cinco mil reais), além da pensão prevista naquele artigo.$a$ where codigo='adct' and numero=54 and titulo='Art. 54-A' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Recursos da seguridade social para a saúde$c$, aplicacao_pratica = $a$Até a aprovação da lei de diretrizes orçamentárias, destina ao setor de saúde no mínimo trinta por cento do orçamento da seguridade social, excluído o seguro-desemprego. Regra transitória vinculada à edição da lei de diretrizes orçamentárias.$a$ where codigo='adct' and numero=55 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Receita da contribuição do Decreto-Lei nº 1.940/1982 para a seguridade$c$, aplicacao_pratica = $a$Até que a lei disponha sobre o art. 195, I, faz integrar a receita da seguridade social a arrecadação de, no mínimo, cinco dos seis décimos percentuais da alíquota da contribuição do Decreto-Lei nº 1.940/1982, com as alterações posteriores que o texto enumera, ressalvados, só no exercício de 1988, os compromissos assumidos com programas e projetos em andamento.$a$ where codigo='adct' and numero=56 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Parcelamento de débitos previdenciários de Estados e Municípios$c$, aplicacao_pratica = $a$Permitiu que Estados e Municípios liquidassem os débitos de contribuições previdenciárias até 30 de junho de 1988 em cento e vinte parcelas mensais, com correção monetária e dispensa de juros e multas, desde que requeressem o parcelamento e iniciassem o pagamento em cento e oitenta dias da promulgação. O § 1º fixou o mínimo de cinco por cento do débito consolidado em cada um dos dois primeiros anos, o § 2º admitiu pagamento por cessão de bens e prestação de serviços (Lei nº 7.578/1986), o § 3º exigiu dotação orçamentária anual e o § 4º previu, no descumprimento, o vencimento total com juros de mora e o bloqueio de parcela dos Fundos de Participação, repassada à previdência. Norma transitória de prazo já exaurido.$a$ where codigo='adct' and numero=57 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Revisão dos benefícios previdenciários em salários mínimos$c$, aplicacao_pratica = $a$Determinou a revisão dos benefícios de prestação continuada mantidos pela previdência social na data da promulgação, para restabelecer o poder aquisitivo, em número de salários mínimos, que tinham na data da concessão, critério de atualização aplicável até a implantação do plano de custeio e benefícios do art. 59. O parágrafo único fixou o pagamento das prestações revistas a partir do sétimo mês da promulgação. Regra transitória limitada a esse período.$a$ where codigo='adct' and numero=58 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Prazos para os planos de custeio e de benefícios da seguridade$c$, aplicacao_pratica = $a$Fixou o prazo máximo de seis meses da promulgação para a apresentação ao Congresso Nacional dos projetos de lei sobre a organização da seguridade social e os planos de custeio e de benefício, com seis meses para a apreciação. O parágrafo único previu a implantação progressiva dos planos nos dezoito meses seguintes à aprovação. Norma transitória de prazos já exauridos.$a$ where codigo='adct' and numero=59 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
update legislacao set contexto = $c$Complementação da União ao Fundeb$c$, aplicacao_pratica = $a$Escalona, a partir de 1º de janeiro de 2021, a complementação da União referida no art. 212-A, IV, da Constituição até alcançar a proporção do inciso V, com valores mínimos de 12% no primeiro ano, 15% no segundo, 17% no terceiro, 19% no quarto, 21% no quinto e 23% no sexto ano (I a VI). O § 1º fixa mínimos para a parcela da alínea "b" do art. 212-A, V (de 2 pontos percentuais no primeiro ano a 10,5 no sexto), e o § 2º fixa os valores da parcela da alínea "c" (de 0,75 ponto percentual no terceiro ano a 2,5 no sexto).$a$ where codigo='adct' and numero=60 and coalesce(titulo,'')='' and inciso is null and paragrafo is null and coalesce(length(aplicacao_pratica),0)=0;
